fn lower_bound(a: &[i64], x: i64) -> usize {
    let (mut lo, mut hi) = (0usize, a.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn upper_bound(a: &[i64], x: i64) -> usize {
    lower_bound(a, x + 1)
}

fn binary_search(a: &[i64], x: i64) -> Option<usize> {
    let i = lower_bound(a, x);
    if i < a.len() && a[i] == x {
        Some(i)
    } else {
        None
    }
}

const INF: i64 = 1 << 60;

fn warshall_floyd(d: &mut [Vec<i64>]) {
    let n = d.len();
    for k in 0..n {
        for i in 0..n {
            if d[i][k] == INF {
                continue;
            }
            for j in 0..n {
                if d[k][j] == INF {
                    continue;
                }
                if d[i][j] > d[i][k] + d[k][j] {
                    d[i][j] = d[i][k] + d[k][j];
                }
            }
        }
    }
}

use std::cmp::Reverse;
use std::collections::BinaryHeap;

const INF: u64 = u64::MAX;

fn dijkstra(g: &[Vec<(usize, u64)>], s: usize) -> Vec<u64> {
    let mut dist = vec![INF; g.len()];
    let mut heap = BinaryHeap::new();
    dist[s] = 0;
    heap.push(Reverse((0u64, s)));
    while let Some(Reverse((d, v))) = heap.pop() {
        if d > dist[v] {
            continue;
        }
        for &(to, w) in &g[v] {
            let nd = d + w;
            if nd < dist[to] {
                dist[to] = nd;
                heap.push(Reverse((nd, to)));
            }
        }
    }
    dist
}

struct Dsu {
    parent: Vec<i32>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Dsu {
            parent: vec![-1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] < 0 {
            return x;
        }
        let root = self.find(self.parent[x] as usize);
        self.parent[x] = root as i32;
        root
    }

    fn unite(&mut self, x: usize, y: usize) -> bool {
        let (mut a, mut b) = (self.find(x), self.find(y));
        if a == b {
            return false;
        }
        if self.parent[a] > self.parent[b] {
            std::mem::swap(&mut a, &mut b);
        }
        self.parent[a] += self.parent[b];
        self.parent[b] = a as i32;
        true
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    fn size(&mut self, x: usize) -> usize {
        let r = self.find(x);
        -self.parent[r] as usize
    }
}

struct SegmentTree {
    size: usize,
    data: Vec<i64>,
}

impl SegmentTree {
    fn new(n: usize) -> Self {
        let mut size = 1;
        while size < n {
            size *= 2;
        }
        SegmentTree {
            size,
            data: vec![0; size * 2],
        }
    }

    fn build(a: &[i64]) -> Self {
        let mut t = SegmentTree::new(a.len());
        for (i, &x) in a.iter().enumerate() {
            t.data[t.size + i] = x;
        }
        for k in (1..t.size).rev() {
            t.data[k] = t.data[k * 2] + t.data[k * 2 + 1];
        }
        t
    }

    fn set(&mut self, i: usize, x: i64) {
        let mut k = i + self.size;
        self.data[k] = x;
        while k > 1 {
            k /= 2;
            self.data[k] = self.data[k * 2] + self.data[k * 2 + 1];
        }
    }

    fn sum(&self, l: usize, r: usize) -> i64 {
        let mut acc = 0;
        let mut lo = l + self.size;
        let mut hi = r + self.size;
        while lo < hi {
            if lo % 2 == 1 {
                acc += self.data[lo];
                lo += 1;
            }
            if hi % 2 == 1 {
                hi -= 1;
                acc += self.data[hi];
            }
            lo /= 2;
            hi /= 2;
        }
        acc
    }
}
